import{_ as s,c as n,o as p,ag as e}from"./chunks/framework.D6L8gzMI.js";const u=JSON.parse('{"title":"YARN 架构与核心组件详解","description":"","frontmatter":{},"headers":[],"relativePath":"hadoop/yarn-architecture.md","filePath":"hadoop/yarn-architecture.md","lastUpdated":1782964899000}'),t={name:"hadoop/yarn-architecture.md"};function i(l,a,c,o,r,d){return p(),n("div",null,a[0]||(a[0]=[e(`<h1 id="yarn-架构与核心组件详解" tabindex="-1">YARN 架构与核心组件详解 <a class="header-anchor" href="#yarn-架构与核心组件详解" aria-label="Permalink to &quot;YARN 架构与核心组件详解&quot;">​</a></h1><p>在 <strong>Hadoop YARN</strong> 中，最容易混淆的就是各种缩写。理解它们之间的关系后，Spark on YARN 的运行流程就很清晰了。</p><h2 id="yarn-整体架构" tabindex="-1">YARN 整体架构 <a class="header-anchor" href="#yarn-整体架构" aria-label="Permalink to &quot;YARN 整体架构&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>+----------------------+</span></span>
<span class="line"><span>|        Client        |</span></span>
<span class="line"><span>+----------+-----------+</span></span>
<span class="line"><span>           |</span></span>
<span class="line"><span>           | 提交 Spark Job</span></span>
<span class="line"><span>           v</span></span>
<span class="line"><span>+----------------------+</span></span>
<span class="line"><span>| ResourceManager (RM) |</span></span>
<span class="line"><span>+----------+-----------+</span></span>
<span class="line"><span>           |</span></span>
<span class="line"><span>           | 分配一个 Container 给 AM</span></span>
<span class="line"><span>           v</span></span>
<span class="line"><span>+-------------------------------+</span></span>
<span class="line"><span>| ApplicationMaster (AM)        |</span></span>
<span class="line"><span>| Spark Driver (Cluster 模式)   |</span></span>
<span class="line"><span>+---------------+---------------+</span></span>
<span class="line"><span>                |</span></span>
<span class="line"><span>                | 向 RM 申请 Executor</span></span>
<span class="line"><span>                v</span></span>
<span class="line"><span>+----------------------+</span></span>
<span class="line"><span>| ResourceManager (RM) |</span></span>
<span class="line"><span>+----------+-----------+</span></span>
<span class="line"><span>           |</span></span>
<span class="line"><span>           | 分配多个 Container</span></span>
<span class="line"><span>           |</span></span>
<span class="line"><span>   +-------+-----------------------+</span></span>
<span class="line"><span>   |                               |</span></span>
<span class="line"><span>   v                               v</span></span>
<span class="line"><span>+----------------------+   +----------------------+</span></span>
<span class="line"><span>| NodeManager (NM)     |   | NodeManager (NM)     |</span></span>
<span class="line"><span>| Container            |   | Container            |</span></span>
<span class="line"><span>| Spark Executor       |   | Spark Executor       |</span></span>
<span class="line"><span>+----------------------+   +----------------------+</span></span></code></pre></div><h2 id="rm-resourcemanager" tabindex="-1">RM（ResourceManager） <a class="header-anchor" href="#rm-resourcemanager" aria-label="Permalink to &quot;RM（ResourceManager）&quot;">​</a></h2><p>RM 是 <strong>整个 YARN 集群的资源管理中心</strong>。</p><p>职责：</p><ul><li>接收应用提交</li><li>管理整个集群资源</li><li>调度资源</li><li>分配 Container</li><li>记录 Application 状态</li></ul><p>可以理解成：</p><blockquote><p>整个集群的「总调度员」</p></blockquote><p>常见 REST：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/ws/v1/cluster/apps</span></span>
<span class="line"><span>/ws/v1/cluster/nodes</span></span>
<span class="line"><span>/ws/v1/cluster/metrics</span></span></code></pre></div><p>默认端口：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>8088</span></span></code></pre></div><h2 id="nm-nodemanager" tabindex="-1">NM（NodeManager） <a class="header-anchor" href="#nm-nodemanager" aria-label="Permalink to &quot;NM（NodeManager）&quot;">​</a></h2><p>每台机器都有一个 NM。</p><p>例如：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>worker01</span></span>
<span class="line"><span>worker02</span></span>
<span class="line"><span>worker03</span></span></code></pre></div><p>每台都会运行：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>NodeManager</span></span></code></pre></div><p>职责：</p><ul><li>启动 Container</li><li>杀死 Container</li><li>收集日志</li><li>汇报资源给 RM</li></ul><p>可以理解成：</p><blockquote><p>每台机器的管家</p></blockquote><p>默认端口：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>8042</span></span></code></pre></div><h2 id="am-applicationmaster" tabindex="-1">AM（ApplicationMaster） <a class="header-anchor" href="#am-applicationmaster" aria-label="Permalink to &quot;AM（ApplicationMaster）&quot;">​</a></h2><p>每个 Application 都会有一个 AM。</p><p>例如：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Spark Job A -&gt; AM1</span></span>
<span class="line"><span>Spark Job B -&gt; AM2</span></span></code></pre></div><p>AM 生命周期：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Job 开始</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>启动 AM</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>申请 Executor</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>监控任务</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>Job 结束</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>AM 退出</span></span></code></pre></div><p>所以：</p><blockquote><p>一个 Job 一个 AM。</p></blockquote><h2 id="container" tabindex="-1">Container <a class="header-anchor" href="#container" aria-label="Permalink to &quot;Container&quot;">​</a></h2><p>Container 不是 Docker。</p><p>它只是：</p><blockquote><p>YARN 分配的一块资源</p></blockquote><p>例如：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>4 Core</span></span>
<span class="line"><span>8 GB</span></span></code></pre></div><p>就是一个 Container。</p><p>里面可以运行：</p><ul><li>AM</li><li>Spark Executor</li><li>Map Task</li><li>Reduce Task</li></ul><p>Container ID 示例：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>container_1751518713616_0001_01_000003</span></span></code></pre></div><h2 id="spark-driver" tabindex="-1">Spark Driver <a class="header-anchor" href="#spark-driver" aria-label="Permalink to &quot;Spark Driver&quot;">​</a></h2><p>很多人把 Driver 和 AM 搞混。</p><p>其实要区分部署模式。</p><h3 id="yarn-client-模式" tabindex="-1">YARN Client 模式 <a class="header-anchor" href="#yarn-client-模式" aria-label="Permalink to &quot;YARN Client 模式&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你的机器</span></span>
<span class="line"><span>  |</span></span>
<span class="line"><span>Driver</span></span>
<span class="line"><span>  |</span></span>
<span class="line"><span>  v</span></span>
<span class="line"><span>RM</span></span></code></pre></div><p>Driver 不在集群中，而是在提交任务的客户端机器上。</p><h3 id="yarn-cluster-模式" tabindex="-1">YARN Cluster 模式 <a class="header-anchor" href="#yarn-cluster-模式" aria-label="Permalink to &quot;YARN Cluster 模式&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>RM</span></span>
<span class="line"><span> |</span></span>
<span class="line"><span> v</span></span>
<span class="line"><span>AM</span></span>
<span class="line"><span> |</span></span>
<span class="line"><span>Driver</span></span></code></pre></div><p>Driver 运行在 AM 里面。</p><p>所以在 Cluster 模式下：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AM == Driver</span></span></code></pre></div><p>这也是为什么 Driver 日志通常就是 AM 日志。</p><h2 id="executor" tabindex="-1">Executor <a class="header-anchor" href="#executor" aria-label="Permalink to &quot;Executor&quot;">​</a></h2><p>Executor 是执行 Task 的 JVM 进程。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Driver</span></span>
<span class="line"><span>  |</span></span>
<span class="line"><span>  +-- Executor1</span></span>
<span class="line"><span>  +-- Executor2</span></span>
<span class="line"><span>  +-- Executor3</span></span></code></pre></div><p>负责：</p><ul><li>执行 Task</li><li>Cache 数据</li><li>Shuffle</li></ul><h2 id="task" tabindex="-1">Task <a class="header-anchor" href="#task" aria-label="Permalink to &quot;Task&quot;">​</a></h2><p>Task 是 Spark 的最小执行单位。</p><p>例如：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>100 个 Partition</span></span></code></pre></div><p>就会产生：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>100 个 Task</span></span></code></pre></div><p>Task 运行在 Executor 里面。</p><h2 id="application" tabindex="-1">Application <a class="header-anchor" href="#application" aria-label="Permalink to &quot;Application&quot;">​</a></h2><p>Application 就是一次应用提交。</p><p>在 Spark 场景下，通常对应一次：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">spark-submit</span></span></code></pre></div><p>例如：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>application_1751518713616_0015</span></span></code></pre></div><p>整个生命周期：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>提交 -&gt; 运行 -&gt; 结束</span></span></code></pre></div><h2 id="appattempt" tabindex="-1">AppAttempt <a class="header-anchor" href="#appattempt" aria-label="Permalink to &quot;AppAttempt&quot;">​</a></h2><p>Application 失败可以重试。</p><p>例如：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Application</span></span>
<span class="line"><span>  ├── Attempt1</span></span>
<span class="line"><span>  └── Attempt2</span></span></code></pre></div><p>Attempt1 失败后，RM 可以重新启动 Attempt2。</p><h2 id="history-server" tabindex="-1">History Server <a class="header-anchor" href="#history-server" aria-label="Permalink to &quot;History Server&quot;">​</a></h2><p>简称 HS。</p><p>职责是保存并展示 Spark 历史任务信息：</p><ul><li>Spark UI</li><li>DAG</li><li>SQL</li><li>Stage</li><li>Executor 信息</li></ul><p>默认端口：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>19888</span></span></code></pre></div><h2 id="timeline-server" tabindex="-1">Timeline Server <a class="header-anchor" href="#timeline-server" aria-label="Permalink to &quot;Timeline Server&quot;">​</a></h2><p>简称 ATS，全称 Application Timeline Server。</p><p>用于保存 Application 生命周期和历史信息。</p><p>很多公司会关闭它，因为比较占资源。</p><h2 id="log-aggregation" tabindex="-1">Log Aggregation <a class="header-anchor" href="#log-aggregation" aria-label="Permalink to &quot;Log Aggregation&quot;">​</a></h2><p>Log Aggregation 不是一个独立进程，而是一套日志聚合机制：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>NodeManager</span></span>
<span class="line"><span>  |</span></span>
<span class="line"><span>  | 上传日志</span></span>
<span class="line"><span>  v</span></span>
<span class="line"><span>HDFS</span></span></code></pre></div><p>作用：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Job 结束</span></span>
<span class="line"><span>stdout / stderr</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>上传 HDFS</span></span></code></pre></div><p>然后通过下面的命令读取：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">yarn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -applicationId</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">application_i</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><h2 id="这些组件之间的关系" tabindex="-1">这些组件之间的关系 <a class="header-anchor" href="#这些组件之间的关系" aria-label="Permalink to &quot;这些组件之间的关系&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Spark Client</span></span>
<span class="line"><span>   |</span></span>
<span class="line"><span>   | spark-submit</span></span>
<span class="line"><span>   v</span></span>
<span class="line"><span>ResourceManager (RM)</span></span>
<span class="line"><span>   |</span></span>
<span class="line"><span>   | 分配 Container 启动 AM</span></span>
<span class="line"><span>   v</span></span>
<span class="line"><span>ApplicationMaster (AM)</span></span>
<span class="line"><span>Cluster 模式下包含 Spark Driver</span></span>
<span class="line"><span>   |</span></span>
<span class="line"><span>   | 向 RM 申请 Executor Container</span></span>
<span class="line"><span>   |</span></span>
<span class="line"><span>   +---------------------------+</span></span>
<span class="line"><span>   |                           |</span></span>
<span class="line"><span>   v                           v</span></span>
<span class="line"><span>NodeManager (NM)          NodeManager (NM)</span></span>
<span class="line"><span>   |                           |</span></span>
<span class="line"><span>Container                  Container</span></span>
<span class="line"><span>   |                           |</span></span>
<span class="line"><span>Spark Executor             Spark Executor</span></span>
<span class="line"><span>   |                           |</span></span>
<span class="line"><span>Task                       Task</span></span></code></pre></div><h2 id="常见缩写速查表" tabindex="-1">常见缩写速查表 <a class="header-anchor" href="#常见缩写速查表" aria-label="Permalink to &quot;常见缩写速查表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>缩写</th><th>全称</th><th>作用</th></tr></thead><tbody><tr><td>RM</td><td>ResourceManager</td><td>全集群资源调度器</td></tr><tr><td>NM</td><td>NodeManager</td><td>每台节点上的资源和容器管理器</td></tr><tr><td>AM</td><td>ApplicationMaster</td><td>单个应用的管理者，负责申请资源、协调执行</td></tr><tr><td>Driver</td><td>Spark Driver</td><td>Spark 程序的控制中心；YARN Cluster 模式下运行在 AM 中</td></tr><tr><td>Executor</td><td>Spark Executor</td><td>执行 Spark Task 的 JVM 进程</td></tr><tr><td>Container</td><td>YARN Container</td><td>YARN 分配的一份 CPU/内存资源，不是 Docker 容器</td></tr><tr><td>Application</td><td>YARN Application</td><td>一次提交的应用，如一次 <code>spark-submit</code></td></tr><tr><td>AppAttempt</td><td>Application Attempt</td><td>应用的一次尝试，失败可重试</td></tr><tr><td>HS</td><td>History Server</td><td>展示 Spark 历史任务和 UI</td></tr><tr><td>ATS</td><td>Application Timeline Server</td><td>保存应用生命周期和历史信息，可选</td></tr><tr><td>HDFS</td><td>Hadoop Distributed File System</td><td>Hadoop 分布式文件系统，日志聚合常存放于此</td></tr></tbody></table><p>理解这些角色后，再看 Spark on YARN 的日志、REST API、资源申请等流程就会容易得多，因为每个组件都有明确的职责和边界。</p>`,104)]))}const g=s(t,[["render",i]]);export{u as __pageData,g as default};
